<?php

namespace App\Http\Controllers;

use App\Models\User;
use App\Services\HaccpTaskGenerator;
use Illuminate\Http\Request;
use Illuminate\Support\Facades\DB;
use Illuminate\Support\Str;
use Illuminate\Validation\Rule;

class HaccpController extends Controller
{
    public function overview(Request $request){$this->admin($request);return response()->json(['roles'=>DB::table('haccp_roles')->orderBy('name')->orderByDesc('version')->get(),'devices'=>DB::table('haccp_devices as d')->leftJoin('haccp_device_types as dt','dt.id','=','d.device_type_id')->whereNull('d.deleted_at')->orderBy('d.location')->orderBy('d.name')->select('d.*','dt.name as device_type_name')->get(),'device_types'=>DB::table('haccp_device_types')->orderBy('name')->get(),'templates'=>DB::table('haccp_templates')->orderBy('category')->orderBy('name')->orderByDesc('version')->get(),'users'=>User::query()->select('id','name','email')->orderBy('name')->get(),'assignments'=>DB::table('haccp_role_user')->get()]);}
    public function today(Request $request,HaccpTaskGenerator $generator){$generator->generate();return response()->json($this->todayQuery($request)->orderBy('t.due_at')->get()->map(fn($task)=>$this->hydrateTask($task)));}
    public function deviceByQr(Request $request,string $token,HaccpTaskGenerator $generator){$device=DB::table('haccp_devices as d')->leftJoin('haccp_device_types as dt','dt.id','=','d.device_type_id')->where('d.qr_token',$token)->whereNull('d.deleted_at')->select('d.*','dt.name as device_type_name')->first();abort_unless($device&&$device->active,404,'HACCP-Gerät nicht gefunden oder inaktiv.');$generator->generate();$tasks=$this->todayQuery($request)->where('t.device_id',$device->id)->orderBy('t.due_at')->get()->map(fn($task)=>$this->hydrateTask($task));return response()->json(['device'=>$device,'tasks'=>$tasks,'open_tasks'=>$tasks->where('status','open')->values()]);}
    public function completeTask(Request $request,int $id){$task=DB::table('haccp_tasks')->find($id);abort_unless($task,404);$this->authorizeTask($request,$task);abort_unless($task->status==='open',422,'Kontrolle wurde bereits bearbeitet.');$snapshot=json_decode($task->snapshot?:'{}',true);$type=$snapshot['result_type']??'checkbox';$data=$request->validate(['numeric_value'=>['nullable','numeric'],'boolean_value'=>['nullable','boolean'],'text_value'=>['nullable','string'],'payload'=>['nullable','array'],'deviation_description'=>['nullable','string'],'corrective_action'=>['nullable','string']]);if(in_array($type,['temperature','number'],true)&&!array_key_exists('numeric_value',$data))abort(422,'Messwert erforderlich.');if(in_array($type,['checkbox','yes_no'],true)&&!array_key_exists('boolean_value',$data))abort(422,'Bestätigung erforderlich.');if(in_array($type,['text','checklist'],true)&&empty(trim((string)($data['text_value']??''))))abort(422,'Kontrollergebnis erforderlich.');$device=$task->device_id?DB::table('haccp_devices')->find($task->device_id):null;$config=$snapshot['configuration']??[];$min=$config['min_value']??$device?->min_value;$max=$config['max_value']??$device?->max_value;$within=null;if(isset($data['numeric_value'])&&($min!==null||$max!==null))$within=($min===null||$data['numeric_value']>=$min)&&($max===null||$data['numeric_value']<=$max);if(in_array($type,['yes_no','checkbox'],true)&&array_key_exists('boolean_value',$data))$within=(bool)$data['boolean_value'];$criticality=$snapshot['criticality']??'normal';$requiresAction=($snapshot['requires_corrective_action']??true)||$criticality==='critical';if($within===false&&$requiresAction&&empty(trim((string)($data['corrective_action']??''))))abort(422,'Bei dieser Abweichung ist eine Korrekturmaßnahme erforderlich.');DB::transaction(function()use($request,$task,$data,$within){$fresh=DB::table('haccp_tasks')->where('id',$task->id)->lockForUpdate()->first();abort_unless($fresh?->status==='open',409,'Kontrolle wurde bereits bearbeitet.');$resultId=DB::table('haccp_task_results')->insertGetId(['task_id'=>$task->id,'completed_by'=>$request->user()->id,'completed_at'=>now(),'numeric_value'=>$data['numeric_value']??null,'boolean_value'=>$data['boolean_value']??null,'text_value'=>$data['text_value']??null,'payload'=>isset($data['payload'])?json_encode($data['payload']):null,'within_limits'=>$within,'created_at'=>now(),'updated_at'=>now()]);if($within===false)DB::table('haccp_deviations')->insert(['task_result_id'=>$resultId,'description'=>$data['deviation_description']??'Grenzwert bzw. Sollzustand nicht eingehalten.','corrective_action'=>$data['corrective_action']??null,'created_at'=>now(),'updated_at'=>now()]);DB::table('haccp_tasks')->where('id',$task->id)->update(['status'=>$within===false?'deviation':'completed','updated_at'=>now()]);});return response()->json(['ok'=>true,'within_limits'=>$within]);}
    public function storeRole(Request $request){$this->admin($request);$data=$this->roleData($request);$data['version']=1;$id=DB::table('haccp_roles')->insertGetId([...$data,'created_at'=>now(),'updated_at'=>now()]);return response()->json(DB::table('haccp_roles')->find($id),201);}
    public function updateRole(Request $request,int $id){$this->admin($request);$role=DB::table('haccp_roles')->find($id);abort_unless($role,404);$data=$this->roleData($request,$id,(int)$role->version);if(!$role->locked_at){DB::table('haccp_roles')->where('id',$id)->update([...$data,'updated_at'=>now()]);return response()->json(DB::table('haccp_roles')->find($id));}$newId=DB::transaction(function()use($role,$data){$userIds=DB::table('haccp_role_user')->where('haccp_role_id',$role->id)->pluck('user_id');DB::table('haccp_roles')->where('id',$role->id)->update(['active'=>false,'updated_at'=>now()]);$newId=DB::table('haccp_roles')->insertGetId([...$data,'version'=>(int)$role->version+1,'supersedes_role_id'=>$role->id,'locked_at'=>null,'created_at'=>now(),'updated_at'=>now()]);foreach($userIds as $userId)DB::table('haccp_role_user')->insertOrIgnore(['haccp_role_id'=>$newId,'user_id'=>$userId]);return $newId;});return response()->json(DB::table('haccp_roles')->find($newId),201);}
    private function roleData(Request $request,?int $id=null,int $version=1):array{return $request->validate(['name'=>['required','string','max:120',Rule::unique('haccp_roles','name')->where(fn($q)=>$q->where('version',$version))->ignore($id)],'description'=>['nullable','string'],'active'=>['boolean']]);}
    public function assignRole(Request $request,int $id){$this->admin($request);$role=DB::table('haccp_roles')->find($id);abort_unless($role,404);abort_if($role->locked_at,409,'Diese Zuständigkeit ist bereits fixiert. Bitte zuerst über Bearbeiten eine neue Version anlegen.');$data=$request->validate(['user_ids'=>['array'],'user_ids.*'=>['integer','exists:users,id']]);DB::transaction(function()use($id,$data){DB::table('haccp_role_user')->where('haccp_role_id',$id)->delete();foreach($data['user_ids']??[] as $userId)DB::table('haccp_role_user')->insert(['haccp_role_id'=>$id,'user_id'=>$userId]);});return response()->noContent();}
    public function storeDevice(Request $request){$this->admin($request);$data=$this->deviceData($request);$id=DB::table('haccp_devices')->insertGetId([...$data,'qr_token'=>Str::random(40),'created_at'=>now(),'updated_at'=>now()]);return response()->json(DB::table('haccp_devices')->find($id),201);}
    public function updateDevice(Request $request,int $id){$this->admin($request);abort_unless(DB::table('haccp_devices')->where('id',$id)->exists(),404);DB::table('haccp_devices')->where('id',$id)->update([...$this->deviceData($request),'updated_at'=>now()]);return response()->json(DB::table('haccp_devices')->find($id));}
    private function deviceData(Request $request):array{$data=$request->validate(['name'=>['required','string','max:160'],'device_type_id'=>['required','exists:haccp_device_types,id'],'location'=>['nullable','string','max:120'],'manufacturer'=>['nullable','string','max:120'],'model'=>['nullable','string','max:120'],'serial_number'=>['nullable','string','max:120'],'commissioned_at'=>['nullable','date'],'min_value'=>['nullable','numeric'],'max_value'=>['nullable','numeric','gte:min_value'],'unit'=>['nullable','string','max:20'],'active'=>['boolean']]);$type=DB::table('haccp_device_types')->find($data['device_type_id']);$data['type']=$type?->name;$data['unit']=$data['unit']??$type?->unit;$data['min_value']=$data['min_value']??$type?->default_min_value;$data['max_value']=$data['max_value']??$type?->default_max_value;return $data;}
    public function storeTemplate(Request $request){$this->admin($request);$data=$this->templateData($request);$id=DB::table('haccp_templates')->insertGetId([...$data,'version'=>1,'created_at'=>now(),'updated_at'=>now()]);return response()->json(DB::table('haccp_templates')->find($id),201);}
    public function updateTemplate(Request $request,int $id){$this->admin($request);$template=DB::table('haccp_templates')->find($id);abort_unless($template,404);$data=$this->templateData($request);if(!$template->locked_at){DB::table('haccp_templates')->where('id',$id)->update([...$data,'updated_at'=>now()]);return response()->json(DB::table('haccp_templates')->find($id));}$newId=DB::transaction(function()use($template,$data){DB::table('haccp_templates')->where('id',$template->id)->update(['active'=>false,'updated_at'=>now()]);return DB::table('haccp_templates')->insertGetId([...$data,'version'=>(int)$template->version+1,'supersedes_template_id'=>$template->id,'locked_at'=>null,'created_at'=>now(),'updated_at'=>now()]);});return response()->json(DB::table('haccp_templates')->find($newId),201);}
    private function templateData(Request $request):array{$data=$request->validate(['name'=>['required','string','max:160'],'category'=>['required','string','max:80'],'criticality'=>['required',Rule::in(['normal','elevated','critical'])],'haccp_role_id'=>['nullable','exists:haccp_roles,id'],'device_id'=>['nullable','exists:haccp_devices,id'],'result_type'=>['required',Rule::in(['checkbox','temperature','number','yes_no','text','checklist'])],'frequency'=>['required',Rule::in(['daily','weekly','monthly','interval'])],'schedule'=>['nullable','array'],'schedule.times'=>['nullable','array','min:1'],'schedule.times.*'=>['date_format:H:i'],'schedule.weekdays'=>['nullable','array','min:1'],'schedule.weekdays.*'=>['integer','between:1,7','distinct'],'schedule.day'=>['nullable','integer','between:1,31'],'schedule.days'=>['nullable','integer','min:1','max:365'],'schedule.window_before_minutes'=>['nullable','integer','min:0','max:1440'],'configuration'=>['nullable','array'],'configuration.min_value'=>['nullable','numeric'],'configuration.max_value'=>['nullable','numeric','gte:configuration.min_value'],'requires_corrective_action'=>['boolean'],'active'=>['boolean']]);$data['schedule']=isset($data['schedule'])?json_encode($data['schedule']):null;$data['configuration']=isset($data['configuration'])?json_encode($data['configuration']):null;$data['requires_corrective_action']=$data['requires_corrective_action']??true;$data['active']=$data['active']??true;return $data;}
    private function todayQuery(Request $request){$roleIds=DB::table('haccp_role_user')->where('user_id',$request->user()->id)->pluck('haccp_role_id');$query=DB::table('haccp_tasks as t')->leftJoin('haccp_devices as d','d.id','=','t.device_id')->leftJoin('haccp_roles as r','r.id','=','t.haccp_role_id')->select('t.*','d.name as device_name','d.location as device_location','d.min_value','d.max_value','d.unit','r.name as role_name')->whereDate('t.due_at',today());if($request->user()->access_role!=='admin')$query->where(fn($q)=>$q->whereNull('t.haccp_role_id')->orWhereIn('t.haccp_role_id',$roleIds));return $query;}
    private function hydrateTask(object $task):object{$task->snapshot=json_decode($task->snapshot?:'{}',true);$config=$task->snapshot['configuration']??[];$task->min_value=$config['min_value']??$task->min_value;$task->max_value=$config['max_value']??$task->max_value;return $task;}
    private function authorizeTask(Request $request,object $task):void{if($request->user()?->access_role==='admin'||$task->haccp_role_id===null)return;$allowed=DB::table('haccp_role_user')->where('haccp_role_id',$task->haccp_role_id)->where('user_id',$request->user()->id)->exists();abort_unless($allowed,403);}
    private function admin(Request $request):void{abort_unless($request->user()?->access_role==='admin',403);}
}
